def subtract(a, b):
    # Filter out empty intervals and sort
    a = sorted([interval for interval in a if interval[0] < interval[1]])
    b = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a:
        return []

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Process each interval in a, subtracting all intervals in merged_b
    result = []
    for a_start, a_end in a:
        current = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            next_current = []
            for c_start, c_end in current:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    next_current.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts that don't overlap
                    if c_start < b_start:
                        next_current.append([c_start, b_start])
                    if c_end > b_end:
                        next_current.append([b_end, c_end])
            current = next_current

        result.extend(current)

    # Merge adjacent/overlapping intervals in result
    if not result:
        return []

    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

